// Fail closed unless exactly one unsent, unapproved August 2026 DRAFT still points to legacy Google Drive.
const rows = $input.all().map((item) => item.json ?? {}).filter((row) => Object.keys(row).length > 0);
if (rows.length !== 1) throw new Error('Recovery denied: expected exactly one DRAFT row');
const row = rows[0];
const clean = (value) => String(value ?? '').trim();
const reportMonth = clean(row.reportMonth);
const reportType = clean(row.reportType).toUpperCase();
const state = clean(row.documentStatus).toUpperCase();
const fileName = clean(row.pdfFileName);
const oldFileId = clean(row.pdfDriveFileId);
const oldUrl = clean(row.pdfDriveUrl);
const approvedAt = clean(row.approvedAt);
const sentAt = clean(row.sentAt);
const reportBody = clean(row.reportBody);
if (reportMonth !== '2026-08' || reportType !== 'MONTHLY_MAINTENANCE' || state !== 'DRAFT' || approvedAt || sentAt) throw new Error('Recovery denied: report is not the expected unsent DRAFT');
if (fileName !== 'Cavetta-Monthly-Maintenance-Report-2026-08.pdf') throw new Error('Recovery denied: unexpected PDF filename');
if (!/^[A-Za-z0-9_-]{10,200}$/.test(oldFileId) || !/^https:\/\/drive\.google\.com\//i.test(oldUrl)) throw new Error('Recovery denied: row is not a legacy Google Drive record');
if (reportBody.length < 20) throw new Error('Recovery denied: stored report body is unavailable');
const objectKey = `Cavetta Maintenance Reports/2026/${fileName}`;
return [{ json: { ...row, reportMonth, reportType, fileName, objectKey } }];

// Rebuild a self-contained PDF source from the authoritative stored DRAFT.
const row = $json;
const escapeHtml = (value) => String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('\"', '&quot;').replaceAll("'", '&#039;');
const title = `Monthly Maintenance Report — ${escapeHtml(row.reportMonthLabel || row.reportMonth)}`;
const status = escapeHtml(String(row.overallResult || 'NO_DATA').toUpperCase());
const generatedAt = escapeHtml(row.generatedAt || 'Not recorded');
const body = escapeHtml(row.reportBody);
const html = `<!doctype html><html><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm}*{box-sizing:border-box}body{font-family:Arial,Helvetica,sans-serif;color:#171717;font-size:10.5pt;line-height:1.5;margin:0}header{border-bottom:2px solid #222;padding-bottom:14px;margin-bottom:22px}h1{font-size:22pt;margin:0 0 6px}.meta{color:#666;font-size:9pt}.badge{display:inline-block;border:1px solid #b89b4c;background:#fff8df;border-radius:999px;padding:4px 9px;font-weight:700;margin:12px 0}.report{white-space:pre-wrap;overflow-wrap:anywhere;border-top:1px solid #ddd;padding-top:16px}footer{border-top:1px solid #ddd;color:#777;font-size:8.5pt;margin-top:26px;padding-top:10px}</style></head><body><header><h1>${title}</h1><div class="meta">Cavetta Properties · CloudIT Pvt Ltd</div><div class="badge">${status} · DRAFT</div><div class="meta">Original report generated: ${generatedAt}</div></header><main class="report">${body}</main><footer>Recovered from the authoritative stored DRAFT and regenerated into private Cloudflare R2 storage. No approval or delivery action was performed.</footer></body></html>`;
return [{ json: { ...row, reportHtml: html } }];

// Verify the generated bytes before any private storage or metadata mutation.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
if (buffer.length < 5 || buffer.length > 25 * 1024 * 1024 || buffer.subarray(0, 5).toString('ascii') !== '%PDF-') throw new Error('Recovery denied: Gotenberg did not return a valid PDF');
const source = $('Validate Recoverable Draft').first().json;
const item = $input.item;
if (!item.binary?.data) throw new Error('Recovery denied: generated binary is missing');
item.binary.data.mimeType = 'application/pdf';
item.binary.data.fileExtension = 'pdf';
item.binary.data.fileName = source.fileName;
item.json = { reportMonth: source.reportMonth, reportType: source.reportType, fileName: source.fileName, objectKey: source.objectKey, byteLength: buffer.length };
return item;

// Build the only Data Table fields this recovery is permitted to replace.
if ($json.success !== true) throw new Error('Recovery denied: R2 upload was not successful');
const source = $('Validate Generated PDF').first().json;
return [{ json: { reportMonth: source.reportMonth, reportType: source.reportType, documentStatus: 'DRAFT', pdfFileName: source.fileName, pdfDriveFileId: source.objectKey, pdfDriveUrl: `r2://cavetta-private-storage/${source.objectKey}`, pdfGeneratedAt: new Date().toISOString() } }];
